# Terraform Module: S3 + RDS + IAM

I'll provide a complete, modular Terraform setup with environment separation via `tfvars` files. This implementation follows the canonical scenario specification.

## Directory Structure

```
.
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
└── .gitignore
```

---

## Module: S3 (`modules/s3/main.tf`)

```hcl
resource "aws_s3_bucket" "app_assets" {
  bucket = var.bucket_name

  tags = {
    Environment = var.environment
    Name        = var.bucket_name
  }
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = var.kms_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key_id
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count = var.enable_cross_region_replication ? 1 : 0

  bucket = aws_s3_bucket.app_assets.id

  depends_on = [aws_s3_bucket_versioning.app_assets]

  role = aws_iam_role.s3_replication[0].arn

  rule {
    id     = "replicate-to-${var.replication_destination_region}"
    status = "Enabled"

    destination {
      bucket       = aws_s3_bucket.replication_destination[0].arn
      storage_class = "STANDARD"

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

resource "aws_s3_bucket" "replication_destination" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = "${var.bucket_name}-${var.replication_destination_region}"
  provider = aws.replica

  tags = {
    Environment = var.environment
    Name        = "${var.bucket_name}-replica"
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count    = var.enable_cross_region_replication ? 1 : 0
  bucket   = aws_s3_bucket.replication_destination[0].id
  provider = aws.replica

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.enable_cross_region_replication ? 1 : 0
  name  = "${var.bucket_name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count = var.enable_cross_region_replication ? 1 : 0
  name  = "${var.bucket_name}-replication-policy"
  role  = aws_iam_role.s3_replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.app_assets.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.app_assets.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "${aws_s3_bucket.replication_destination[0].arn}/*"
      }
    ]
  })
}
```

## Module: S3 (`modules/s3/variables.tf`)

```hcl
variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
}

variable "environment" {
  description = "Environment name (dev, prod)"
  type        = string
}

variable "kms_key_id" {
  description = "Optional KMS key ID for encryption. If null, uses AES256"
  type        = string
  default     = null
}

variable "enable_cross_region_replication" {
  description = "Enable cross-region replication"
  type        = bool
  default     = false
}

variable "replication_destination_region" {
  description = "Destination region for cross-region replication"
  type        = string
  default     = "us-west-2"
}
```

## Module: S3 (`modules/s3/outputs.tf`)

```hcl
output "bucket_id" {
  description = "The name of the S3 bucket"
  value       = aws_s3_bucket.app_assets.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = aws_s3_bucket.app_assets.arn
}

output "bucket_region" {
  description = "The AWS region this bucket resides in"
