## Module: RDS (`modules/rds/main.tf`)

```hcl
resource "aws_db_subnet_group" "postgres" {
  name       = "${var.instance_identifier}-subnet-group"
  subnet_ids = var.database_subnets

  tags = {
    Environment = var.environment
  }
}

resource "aws_security_group" "postgres" {
  name        = "${var.instance_identifier}-sg"
  description = "Security group for RDS PostgreSQL"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_groups
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.environment
  }
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_db_instance" "postgres" {
  identifier            = var.instance_identifier
  engine               = "postgres"
  engine_version       = var.engine_version
  instance_class       = var.instance_class
  allocated_storage    = var.allocated_storage
  storage_type         = "gp3"
  storage_encrypted    = true

  db_name              = var.database_name
  username             = var.master_username
  password             = random_password.db_password.result

  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.postgres.id]

  publicly_accessible        = false
  multi_az                   = var.multi_az
  backup_retention_period    = var.backup_retention_days
  backup_window             = "03:00-04:00"
  maintenance_window        = "sun:04:00-sun:05:00"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.instance_identifier}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  enable_cloudwatch_logs_exports = ["postgresql"]
  enable_iam_database_authentication = var.enable_iam_auth

  tags = {
    Environment = var.environment
  }

  depends_on = [aws_security_group.postgres]
}

resource "aws_secretsmanager_secret" "db_password" {
  name                    = "${var.instance_identifier}-password"
  recovery_window_in_days = 7

  tags = {
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id = aws_secretsmanager_secret.db_password.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.db_password.result
    engine   = "postgres"
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = var.database_name
  })
}
```

## Module: RDS (`modules/rds/variables.tf`)

```hcl
variable "instance_identifier" {
  description = "Name of the RDS instance"
  type        = string
}

variable "instance_class" {
  description = "Instance class (e.g., db.t3.micro, db.t3.medium)"
  type        = string
}

variable "environment" {
  description = "Environment name (dev, prod)"
  type        = string
}

variable "engine_version" {
  description = "PostgreSQL engine version"
  type        = string
