## Module: IAM (`modules/iam/main.tf`)

```hcl
# Service account role for application
resource "aws_iam_role" "service_account" {
  name               = "${var.service_account_name}-role"
  assume_role_policy = var.assume_role_policy

  tags = {
    Environment = var.environment
  }
}

# Policy for S3 bucket access
resource "aws_iam_role_policy" "s3_access" {
  name   = "${var.service_account_name}-s3-policy"
  role   = aws_iam_role.service_account.id
  policy = var.environment == "prod" ? data.aws_iam_policy_document.s3_access_prod[0].json : data.aws_iam_policy_document.s3_access_dev[0].json
}

data "aws_iam_policy_document" "s3_access_dev" {
  count = var.environment == "dev" ? 1 : 0
  statement {
    sid    = "S3BucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket"
    ]
    resources = [
      var.s3_bucket_arn,
      "${var.s3_bucket_arn}/*"
    ]
  }
}

data "aws_iam_policy_document" "s3_access_prod" {
  count = var.environment == "prod" ? 1 : 0
  statement {
    sid       = "S3BucketListAccess"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [var.s3_bucket_arn]
  }

  statement {
    sid    = "S3BucketObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = ["${var.s3_bucket_arn}/*"]
  }
}

# Policy for RDS access (optional, if using IAM database auth)
resource "aws_iam_role_policy" "rds_access" {
  count  = var.enable_rds_iam_auth ? 1 : 0
  name   = "${var.service_account_name}-rds-policy"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.rds_access[0].json
}

data "aws_iam_policy_document" "rds_access" {
  count = var.enable_rds_iam_auth ? 1 : 0
  statement {
    sid    = "RDSConnect"
    effect = "Allow"
    actions = [
      "rds-db:connect"
    ]
    resources = [
      "arn:aws:rds:${var.aws_region}:${var.aws_account_id}:db:${var.rds_instance_id}"
    ]
  }
}

# Policy for Secrets Manager access (to read DB credentials)
resource "aws_iam_role_policy" "secrets_access" {
  count  = var.enable_secrets_access ? 1 : 0
  name   = "${var.service_account_name}-secrets-policy"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.secrets_access[0].json
}

data "aws_iam_policy_document" "secrets_access" {
  count = var.enable_secrets_access ? 1 : 0
  statement {
    sid    = "SecretsManagerRead"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [var.db_secret_arn]
  }
}

# IAM user for programmatic access (dev only)
resource "aws_iam_user" "service_account" {
  count = var.environment == "dev" && var.create_iam_user ? 1 : 0
  name  = "${var.service_account_name}-user"

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_user_policy_attachment" "service_account" {
  count      = var.environment == "dev" && var.create_iam_user ? 1 : 0
  user       = aws_iam_user.service_account[0].name
  policy_arn = aws_iam_role_policy.s3_access.arn
}

resource "aws_iam_access_key" "service_account" {
  count = var.environment == "dev" && var.create_iam_user ? 1 : 0
  user  = aws_iam_user.service_account[0].name
}
```

