## Root Module (`main.tf`)

```hcl
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  backend "s3" {
    # Configure via -backend-config flags or environment variables
    # bucket         = "my-tf-state"
    # key            = "infrastructure/terraform.tfstate"
    # region         = "us-east-1"
    # encrypt        = true
    # dynamodb_table = "terraform-locks"
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "Terraform"
      CreatedAt   = formatdate("YYYY-MM-DD", timestamp())
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = var.replication_destination_region

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

# S3 Module
module "s3" {
  source = "./modules/s3"

  bucket_name                       = var.s3_bucket_name
  environment                       = var.environment
  kms_key_id                        = var.s3_kms_key_id
  enable_cross_region_replication   = var.enable_s3_replication
  replication_destination_region    = var.replication_destination_region
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  instance_identifier    = var.rds_instance_name
  instance_class         = var.rds_instance_class
  environment            = var.environment
  engine_version         = var.postgres_version
  allocated_storage      = var.rds_allocated_storage
  database_name          = var.rds_database_name
  multi_az               = var.rds_multi_az
  backup_retention_days  = var.rds_backup_retention_days
  enable_iam_auth        = var.enable_rds_iam_auth
  vpc_id                 = var.vpc_id
  database_subnets       = var.database_subnets
  allowed_security_groups = [var.app_security_group_id]
}

# IAM Module
module "iam" {
  source = "./modules/iam"

  service_account_name   = var.service_account_name
  environment            = var.environment
  s3_bucket_arn          = module.s3.bucket_arn
  db_secret_arn          = module.rds.db_secret_arn
  assume_role_policy     = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.aws_account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  enable_rds_iam_auth    = var.enable_rds_iam_auth
  rds_instance_id        = module.rds.db_instance_id
  enable_secrets_access  = true
  aws_region             = var.aws_region
  aws_account_id         = var.aws_account_id
  create_iam_user        = var.environment == "dev"
}
```

